INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3), 'أكمل: الشرائح الحالية والإعفاء الشخصي 20,000 جنيه جايين من القانون رقم ______.', '["206 لسنة 2020","6 لسنة 2025","91 لسنة 2005","7 لسنة 2024"]', 3, 'القانون 7 لسنة 2024 عدّل المادة 8 (الشرائح) والمادة 13 (الإعفاء الشخصي). القانون 91 هو الأصل، و6 لسنة 2025 قانون التسهيلات، و206 قانون الإجراءات. (الوحدة 3.1)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3) AND body = 'أكمل: الشرائح الحالية والإعفاء الشخصي 20,000 جنيه جايين من القانون رقم ______.');
