INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3), 'أكمل: الدخول اللي صافيها أكتر من ______ جنيه الشرائح الأقل بتختفي فيها بالتدريج.', '["1,200,000","600,000","400,000","200,000"]', 1, 'المادة 8: لحد 600,000 الجدول العادي، وفوقها بتبدأ الشرائح الأقل تختفي. (الوحدة 3.2)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3) AND body = 'أكمل: الدخول اللي صافيها أكتر من ______ جنيه الشرائح الأقل بتختفي فيها بالتدريج.');
