INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3), 'اكتشف الخطأ: سارة حسبت ضريبة هشام (صافيه 750,000) بالجدول العادي فطلعت 162,250. التصحيح:', '["206,250 لأن الدخل كله 27.5%","169,000 لأنه في فئة 700-800 ألف والحسبة بتبدأ من 15% على أول 70,000","187,500 لأن الدخل كله 25%","162,250 صح ومفيش خطأ"]', 1, 'فوق 600,000 لازم تحدد الفئة الأول. فئة 700-800 ألف خسرت الشريحتين الأولى والتانية، والفرق 6,750. (الوحدة 3.2)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3) AND body = 'اكتشف الخطأ: سارة حسبت ضريبة هشام (صافيه 750,000) بالجدول العادي فطلعت 162,250. التصحيح:');
INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3), 'اكتشف الخطأ: محاسب أضاف لدخل الموظفين قيمة الوجبة والأتوبيس الجماعي وحسب عليهم ضريبة. التصحيح:', '["يضيف الوجبة بس والأتوبيس معفي","كلامه صح لأن كل المزايا العينية بتتضاف","يضيف 20% منهم بس","الوجبة والنقل الجماعي مزايا جماعية معفاة ومايتضافوش للدخل"]', 3, 'المادة 13 بتعفي الوجبة والنقل الجماعي والرعاية الصحية وأدوات وملابس العمل والسكن لظروف الشغل. (الوحدة 3.3)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3) AND body = 'اكتشف الخطأ: محاسب أضاف لدخل الموظفين قيمة الوجبة والأتوبيس الجماعي وحسب عليهم ضريبة. التصحيح:');
INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3), 'اكتشف الخطأ: شركة طبقت الإعفاء الشخصي والشرائح على موظف بدوام جزئي عنده جهة عمل أصلية تانية. التصحيح:', '["تخصم 5% بس","التطبيق صح لأن كل موظف ليه إعفاء","تخصم 10% قطعي لأنها جهة غير أصلية، والإعفاء من الجهة الأصلية بس","ماتخصمش حاجة لأن الجهة الأصلية بتخصم"]', 2, 'كده الإعفاء بيتاخد مرتين، والفرق بيطلع على الشركة في الفحص. (الوحدة 3.4)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3) AND body = 'اكتشف الخطأ: شركة طبقت الإعفاء الشخصي والشرائح على موظف بدوام جزئي عنده جهة عمل أصلية تانية. التصحيح:');
INSERT INTO questions (exam_id, body, options, answer, explanation) SELECT (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3), 'اكتشف الخطأ: سارة خصمت من محمود 592.50 بس في ديسمبر رغم إنه خد مكافأة 12,000. التصحيح:', '["592.50 صح لأن المكافأة معفاة","خصم ديسمبر 1,200 (10% من المكافأة)","المكافأة تتأجل لتسوية يناير من غير خصم","خصم ديسمبر 2,992.50 على أساس الحسبة السنوية، وإلا يطلع فرق 2,400 في التسوية"]', 3, 'الضريبة السنوية 9,510 − 6,517.50 المخصوم = 2,992.50. الفرق 2,400 الشركة هتتلزم تسدده لو ماتخصمش. (الوحدة 3.5)' WHERE NOT EXISTS (SELECT 1 FROM questions WHERE exam_id = (SELECT e.id FROM exams e JOIN courses c ON c.id = e.course_id WHERE c.slug = 'tax' AND e.kind = 'level' AND e.after_level = 3) AND body = 'اكتشف الخطأ: سارة خصمت من محمود 592.50 بس في ديسمبر رغم إنه خد مكافأة 12,000. التصحيح:');
